def main():
    if not os.path.exists(SOURCE_JSON):
        print(f"Error: Source file {SOURCE_JSON} not found.")
        return

    with open(SOURCE_JSON, "r", encoding="utf-8") as f:
        data = json.load(f)

    full_text_joined = "\n\n".join(FULL_TEXT_CHUNKS)
    data["full_text"] = full_text_joined
    
    print(f"Hydrating {SOURCE_JSON} with {len(full_text_joined)} characters of full text...")

    with open(TARGET_JSON, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    print(f"Successfully created {TARGET_JSON}")

if __name__ == "__main__":
    main()
